import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (type.isInstance(thrown)) return;
            throw new AssertionError("Expected " + type.getName() + " but got " + thrown, thrown);
        }
        throw new AssertionError("Expected " + type.getName());
    }

    public static void main(String[] args) {
        List<String> input = new ArrayList<>(Arrays.asList("a", null, "c", "d", "e"));
        List<String> first = Solution.slice(input, 1, 2);
        check(first.equals(Arrays.asList("a", null)), "first one-based page");
        List<String> second = Solution.slice(input, 2, 2);
        check(second.equals(Arrays.asList("c", "d")), "second page");
        List<String> last = Solution.slice(input, 3, 2);
        check(last.equals(Collections.singletonList("e")), "partial last page");
        check(input.equals(Arrays.asList("a", null, "c", "d", "e")), "input mutated");
        check(first != input, "page must be fresh");
        expect(UnsupportedOperationException.class, () -> first.set(0, "x"));

        input.set(0, "changed");
        check(first.get(0).equals("a"), "result aliases input");

        List<String> beyond = Solution.slice(input, 4, 2);
        check(beyond.isEmpty(), "page beyond input");
        expect(UnsupportedOperationException.class, () -> beyond.add("x"));
        check(Solution.slice(Collections.emptyList(), 1, 1).isEmpty(), "empty input");
        check(Solution.slice(input, Integer.MAX_VALUE, 1000).isEmpty(), "overflow-safe offset");

        expect(NullPointerException.class, () -> Solution.slice(null, 1, 1));
        expect(IllegalArgumentException.class, () -> Solution.slice(input, 0, 1));
        expect(IllegalArgumentException.class, () -> Solution.slice(input, -1, 1));
        expect(IllegalArgumentException.class, () -> Solution.slice(input, 1, 0));
        expect(IllegalArgumentException.class, () -> Solution.slice(input, 1, 1001));

        List<String> boundary = new ArrayList<>();
        for (int i = 0; i < 1000; i++) boundary.add(Integer.toString(i));
        List<String> maxPage = Solution.slice(boundary, 1, 1000);
        check(maxPage.size() == 1000 && maxPage.get(999).equals("999"), "maximum page size boundary");
    }
}

